// Parse Meta Cloud API webhook payload
const body = $json.body || $json;
const entry = body.entry || [];

if (!entry.length) return [{ json: { skip: true } }];

const changes = entry[0]?.changes || [];
if (!changes.length) return [{ json: { skip: true } }];

const value = changes[0]?.value;
if (!value || !value.messages || !value.messages.length) {
  return [{ json: { skip: true } }];
}

const msg = value.messages[0];
const contacts = value.contacts || [];
const contact = contacts.find(c => c.wa_id === msg.from) || {};
const metadata = value.metadata || {};

// Extract message body based on type
let messageBody = '';
let hasMedia = false;
let mediaUrl = null;
let mediaMimetype = null;

switch (msg.type) {
  case 'text':
    messageBody = msg.text?.body || '';
    break;
  case 'image':
    messageBody = msg.image?.caption || '';
    hasMedia = true;
    mediaMimetype = 'image/jpeg';
    break;
  case 'video':
    messageBody = msg.video?.caption || '';
    hasMedia = true;
    mediaMimetype = 'video/mp4';
    break;
  case 'audio':
    messageBody = '';
    hasMedia = true;
    mediaMimetype = 'audio/ogg';
    break;
  case 'document':
    messageBody = msg.document?.caption || msg.document?.filename || '';
    hasMedia = true;
    mediaMimetype = msg.document?.mime_type || 'application/pdf';
    break;
  case 'sticker':
    messageBody = '';
    hasMedia = true;
    mediaMimetype = 'image/webp';
    break;
  case 'location':
    messageBody = `📍 Lokasi: ${msg.location?.latitude}, ${msg.location?.longitude}`;
    break;
  default:
    messageBody = `(${msg.type})`;
}

// Get media ID for downloading
const mediaId = msg[msg.type]?.id || null;

return [{
  json: {
    skip: false,
    // Meta-specific fields
    phoneNumberId: metadata.phone_number_id,
    displayPhoneNumber: metadata.display_phone_number,
    // Message data
    from: msg.from,
    messageId: msg.id,
    timestamp: msg.timestamp,
    type: msg.type,
    body: messageBody,
    // Contact
    contactName: contact.profile?.name || msg.from,
    // Media
    hasMedia: hasMedia,
    mediaId: mediaId,
    mediaMimetype: mediaMimetype,
    // Session identifier for DB lookups
    sessionId: `meta_${metadata.phone_number_id}`
  }
}];

const trigger = items[0].json;
const senderId = trigger.from || '';
const message = trigger.body || '';

if (!senderId) { throw new Error('Sender ID tidak ditemukan dari Meta webhook'); }

return {
  json: {
    mode: 'production',
    message: message,
    sessionId: senderId,
    chatId: senderId,
    agentConfig: null,
    // Pass through Meta fields
    phoneNumberId: trigger.phoneNumberId,
    contactName: trigger.contactName,
    messageType: trigger.type,
    hasMedia: trigger.hasMedia,
    mediaId: trigger.mediaId,
    mediaMimetype: trigger.mediaMimetype,
    metaSessionId: trigger.sessionId
  }
};

const input = $input.first().json.body;
return {
  json: {
    mode: 'simulation',
    message: input.message,
    sessionId: input.sessionId,
    agentConfig: input.agentConfig
  }
};

const originalData = $('Merge Inputs').item.json;
const data = items[0].json;
let finalPrompt = "";
let finalKnowledge = "";
let finalFollowup = null;

if (originalData.mode === 'production') {
    finalPrompt = data.system_prompt || "";
    finalKnowledge = data.knowledge || "";
    finalFollowup = data.followup_config || null;

    if (finalKnowledge.includes('Attached File')) {
        finalPrompt += "\n\nATURAN GAMBAR/FILE:\n";
        finalPrompt += "Jika CONTEXT mengandung 'Attached File (nama): URL', kamu WAJIB menyertakan URL gambar tersebut di dalam response-mu.\n";
        finalPrompt += "Format: tulis URL gambar langsung di response, contoh: https://minio.example.com/gambar.jpg\n";
        finalPrompt += "Jangan sembunyikan URL gambar. Jika user bertanya tentang topik yang memiliki Attached File, SELALU sertakan URL file tersebut di response.\n";
        finalPrompt += "JANGAN escalate jika informasi (termasuk gambar) sudah tersedia di CONTEXT.";
    }

    let hc = data.handover_config;
    if (typeof hc === 'string') {
        try { hc = JSON.parse(hc); } catch(e) { hc = null; }
    }

    if (hc && hc.enabled) {
        const rules = [];
        rules.push("\nPENTING - ATURAN ESCALATION:");
        rules.push("Kamu WAJIB menyertakan JSON {\"escalate\": true, \"reason\": \"<alasan>\"} di BARIS TERAKHIR response-mu jika salah satu kondisi berikut terpenuhi:");
        if (hc.escalationPrompt && hc.escalationPrompt.trim()) {
            rules.push("");
            rules.push("KONDISI ESCALATION:");
            hc.escalationPrompt.trim().split('\n').forEach(line => {
                if (line.trim()) rules.push("• " + line.trim());
            });
        }
        rules.push("");
        rules.push("PENTING: JANGAN escalate jika pertanyaan user BISA dijawab dari CONTEXT yang tersedia.");
        rules.push("");
        rules.push("FORMAT OUTPUT SAAT ESCALATION:");
        rules.push('Balas user dengan sopan, lalu DI BARIS TERAKHIR tulis: {"escalate": true, "reason": "<alasan singkat>"}');
        rules.push("");
        rules.push("Jika TIDAK perlu escalation, JANGAN sertakan JSON escalate di response.");
        finalPrompt += "\n\n" + rules.join("\n");
    }
} else {
    finalPrompt = data.agentConfig?.systemInstruction || "";
    finalKnowledge = data.agentConfig?.knowledgeBase || "";
    finalFollowup = data.agentConfig?.followupConfig || null;
    if (finalKnowledge.includes('Attached File')) {
        finalPrompt += "\n\nATURAN GAMBAR/FILE:\n";
        finalPrompt += "Jika CONTEXT mengandung 'Attached File (nama): URL', kamu WAJIB menyertakan URL tersebut di dalam response-mu.\n";
        finalPrompt += "Format: tulis URL file langsung di response.";
    }
}

return { json: { ...originalData, ...data, finalSystemPrompt: finalPrompt, finalKnowledge: finalKnowledge, followupConfig: finalFollowup } };

const aiOutput = items[0].json.output;
const agentData = $('AI Agent').item.json;
let finalMessageForUser = aiOutput;
let welcomeImageUrl = null;
let bookingData = { booking: false, escalate: false };
let promptTokens = agentData?.response_metadata?.tokenUsage?.promptTokens || agentData?.usage_metadata?.prompt_token_count || 0;
let completionTokens = agentData?.response_metadata?.tokenUsage?.completionTokens || agentData?.usage_metadata?.candidates_token_count || 0;

if (promptTokens === 0 || completionTokens === 0) {
    const ctx = $('Finalize Context').first().json;
    const userMessage = $('Set Prod Mode').first().json.message || "";
    const fullInputText = (ctx.finalSystemPrompt || "") + (ctx.finalKnowledge || "") + userMessage;
    promptTokens = Math.ceil(fullInputText.length / 4);
    completionTokens = Math.ceil((aiOutput || "").length / 4);
}
let totalTokens = promptTokens + completionTokens;

try {
    if (!aiOutput) throw new Error("Output kosong");

    const jsonMatch = aiOutput.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
        let jsonString = jsonMatch[0];
        jsonString = jsonString.replace(/^json\s*/i, "").replace(/$/i, "");
        jsonString = jsonString.replace(/\\(?!["\\bfnrtu])/g, "\\\\\");
        const parsed = JSON.parse(jsonString);
        if (parsed.booking && String(parsed.booking).toLowerCase() === 'true') {
            bookingData.booking = true;
            bookingData.topic = parsed.topic;
            bookingData.clientEmail = parsed.clientEmail;
            let time = parsed.startTime ? parsed.startTime.replace(' ', 'T') : '';
            if (time && time.split(':').length === 2) { time = time.includes('+') ? time.split('+')[0] + ':00+' + time.split('+')[1] : time + ':00'; }
            if (time && !time.includes('+') && !time.endsWith('Z')) time += '+07:00';
            bookingData.startTime = time;
        }
        if (parsed.escalate && String(parsed.escalate).toLowerCase() === 'true') { bookingData.escalate = true; }

        finalMessageForUser = aiOutput.replace(/json[\s\S]*/g, "").trim();
        finalMessageForUser = finalMessageForUser.replace(/\{[\s\S]*\}/g, "").trim();
        finalMessageForUser = finalMessageForUser.replace(/`/g, "").trim();
    }

    // Capture image URLs
    const mdRegex = /\[([^\]]*)\]\((https?:\/\/[^\s)]+\.(?:png|jpg|jpeg|gif|webp|pdf)(?:\?[^\s)]*)?)\)/i;
    const rawRegex = /(https?:\/\/[^\s]+\.(?:png|jpg|jpeg|gif|webp|pdf)(?:\?[^\s]*)?)/i;

    const mdMatch = finalMessageForUser.match(mdRegex);
    if (mdMatch) {
        welcomeImageUrl = mdMatch[2];
        finalMessageForUser = finalMessageForUser.replace(mdMatch[0], "").trim();
    } else {
        const rawMatch = finalMessageForUser.match(rawRegex);
        if (rawMatch) {
            welcomeImageUrl = rawMatch[1];
            finalMessageForUser = finalMessageForUser.replace(rawMatch[0], "").trim();
        }
    }

    const imgMatch = finalMessageForUser.match(/WELCOME_IMAGE_URL:\s*(\S+)/i);
    if (imgMatch && imgMatch[1]) {
        welcomeImageUrl = imgMatch[1].trim();
        finalMessageForUser = finalMessageForUser.replace(/WELCOME_IMAGE_URL:\s*\S+/i, "").trim();
    }
} catch (error) { 
    bookingData.error = error.message; 
}

return [{ 
    json: { 
        ...bookingData, 
        welcome_image_url: welcomeImageUrl,
        text_for_wa: finalMessageForUser, 
        output: finalMessageForUser, 
        tokens: { prompt: promptTokens, completion: completionTokens, total: totalTokens } 
    } 
}];

const ctx = $('Finalize Context').item.json;
const followup = ctx.followupConfig || {};
const delay = Number(followup.delay) || 15;
const unit = followup.unit === 'hours' ? 'hours' : 'minutes';
let text = followup.prompt || "";
text = text.replace(/<[^>]*>/g, "").replace(/&nbsp;/g, " ").trim();
return { json: { ...$json, followup_delay_amount: delay, followup_delay_unit: unit, followup_text: text } };

const aiOutput = items[0].json.output || "";
let text = aiOutput;
let imageUrl = null;

const mdRegex = /\[([^\]]*)\]\((https?:\/\/[^\s)]+\.(?:png|jpg|jpeg|gif|webp|pdf)(?:\?[^\s)]*)?)\)/i;
const rawRegex = /(https?:\/\/[^\s]+\.(?:png|jpg|jpeg|gif|webp|pdf)(?:\?[^\s]*)?)/i;

const mdMatch = text.match(mdRegex);
if (mdMatch) {
    imageUrl = mdMatch[2];
    text = text.replace(mdMatch[0], "").trim();
} else {
    const rawMatch = text.match(rawRegex);
    if (rawMatch) {
        imageUrl = rawMatch[1];
        text = text.replace(rawMatch[0], "").trim();
    }
}

return [{ json: { output: text, welcome_image_url: imageUrl } }];
